npx tsx -e "
import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
const base='.sofar/initiatives'
const creators = new Map()
const sessionInitiatives = new Map()
for (const slug of readdirSync(base)) {
  let lines
  try { lines = readFileSync(join(base, slug, 'events.jsonl'), 'utf8').split('\n') } catch { continue }
  for (const l of lines) {
    if (!l.trim()) continue
    let e; try { e = JSON.parse(l) } catch { continue }
    if (e.type === 'initiative_created') creators.set(slug, e.session)
    if (e.type === 'session_started') {
      if (!sessionInitiatives.has(e.session)) sessionInitiatives.set(e.session, new Set())
      sessionInitiatives.get(e.session).add(slug)
    }
  }
}
const creatorSessions = [...creators.values()]
const uniq = new Set(creatorSessions)
console.log('initiatives with a creation event :', creatorSessions.length)
console.log('distinct creating sessions        :', uniq.size)
const dupes = creatorSessions.filter((s,i)=>creatorSessions.indexOf(s)!==i)
console.log('sessions that created >1          :', new Set(dupes).size)
const multi = [...sessionInitiatives.values()].filter(s => s.size > 1).length
console.log('sessions registered in >1 record  :', multi, 'of', sessionInitiatives.size)
" 2>&1 | tail -6

